logger = system.util.getLogger("HitachiUX2")

selectedProduct = self.view.rootContainer.custom.selectedProduct

if selectedProduct is None or str(selectedProduct).strip() == "":
    logger.warn("Enter pressed with no product selected.")
    return

selectedProduct = str(selectedProduct).strip()

tagPaths = [
    "[default]sander_falldown/falldown/product/product_start_time",
    "[default]Hitachi_UX2/product_description"
]

tagValues = [
    system.date.now(),
    selectedProduct
]

writeResults = system.tag.writeBlocking(
    tagPaths,
    tagValues
)

for index, writeResult in enumerate(writeResults):

    if not writeResult.isGood():

        logger.error(
            "Failed to write tag %s. Quality: %s"
            % (
                tagPaths[index],
                str(writeResult)
            )
        )

        return

def delayedPrinterTrigger():

    import time
    time.sleep(0.75)

    triggerPath = "[default]Hitachi_UX2/ResendTrigger"

    triggerValue = system.tag.readBlocking(
        [triggerPath]
    )[0]

    if triggerValue.quality.isGood():

        newTriggerValue = int(triggerValue.value) + 1

        triggerWriteResult = system.tag.writeBlocking(
            [triggerPath],
            [newTriggerValue]
        )[0]

        if not triggerWriteResult.isGood():

            logger.error(
                "Failed to increment ResendTrigger. Quality: %s"
                % str(triggerWriteResult)
            )

    else:

        logger.error(
            "Could not read ResendTrigger. Quality: %s"
            % str(triggerValue.quality)
        )

system.util.invokeAsynchronous(
    delayedPrinterTrigger
)

system.perspective.navigate(
    page="/Grade_Sheet"
)
